INSERT INTO `quizzes` (`id`, `correct_answers`, `image_url`, `sentence`, `title`, `words`, `quiz_type`) VALUES
(1, 'le,a', '', 'L\'infirmière aide____malade qui____mal à la tête', 'préposition,conjonction de coordination-Grammaire', 'le,a', NULL),
(2, 'belle,beau', '', 'La fleur est____et le jardin est_____.', 'Accords des adjectifs - Grammaire', 'beau,belle', NULL),
(3, 'il,nous,tu', '', '____mange une pomme alors que ____ regardons un film et que  ____ dors.', 'Les pronoms - Grammaire', 'nous,il,tu', NULL),
(4, 'grandes,grands', '', 'Ces fleurs sont____et ces arbres sont____.', 'Les Adjectifs(Accord au pluriel) - Grammaire', 'grandes,grands', NULL),
(6, 'hier,demain,aujourd\'hui,la semaine prochaine', '', 'je pars____.Nous avons étudié____.Elle viendra____.Ils voyageront____.', 'Les Expressions de temps - Grammaire', 'aujourd\'hui,hier,la semaine prochaine,demain     ', NULL),
(7, 'parlerai,irons,trouveras,feront', '', 'Je____français demain.Nous____à Paris la semaine prochaine.Tu____un nouveau travail bientôt.Ils____leurs devoirs ce soir.', 'Futur simple - Grammaire', 'trouveras,parlerai,feront,irons', NULL),
(8, 'ce,cette,ces,cet', '', '____livre est intérressant.____voiture est rapide.____étudiants sont motivés.____hôtel est beau .', 'Adjectifs démonstratifs - Grammaire', 'ces,ce,cette,cet', NULL),
(9, 'parle,mangeons,écoutes,travaillent', '', 'Je____français(parler).Nous____ensemble(manger).Tu____la musique(écouter).Ils____vite(travailler).', 'Verbes réguliers - Grammaire', 'écoutes,parle,travaillent,mangeons', NULL),
(10, 'convocations,reportée,réserver', NULL, 'Avant la réunion on envoie des____,La réunion à été____ à vendredi,On doit____ une salle de conférences.', 'Au Bureau', 'confirmer,réserver,décidée,reportée,participations,convocations', NULL),
(11, 'bien,remercie,reçu,appeler,présente', '', 'Nous avons______  reçu votre courrier du 17 Juin dernier .Je vous en____ par avance .J\'ai bien____ les documents que vous m\'avez transmis. N\'hésitez pa à m\'____ si vous avez des questions. Je vous____ Michel Garnier. ', 'Au Bureau', 'mal,bien,contacte,remercie,envoyé,reçu,appeler,envoyer,présente,prépare', NULL),
(12, 'vrai,vrai,faux,faux,faux,vrai', '', '1-Pour demander le nom d\'un collègue, vous dites :comment s\'appelle t-il ?____.\r\n2-Si vous présentez quelqu\'un ,vous dites : je vous présente monsieur Fabre____.\r\n3-Pour vérifier l\'heure de la réunion , vous dites :Je confirme bien l\'heure de la réunion____.\r\n4-On peut finir un courriel à un nouveau client en écrivant : salut , à bientôt____.\r\n5-Si vous confirmez votre participation , vous dites : il y a bien une réunion ?____.\r\n6-Vous pouvez finir un courrier électronique par : n\'hésitez pas à me contacter____.\r\n', 'Au Bureau', 'vrai,faux,faux,faux,vrai,vrai', NULL),
(16, 'vrai,vrai,vrai,vrai,vrai', '', '1-Clotilde téléphone souvent à Babette____\r\n2-Babette n\'accepte jamais les invitations____\r\n3-Jean-Paul ne donne pas le numéro de mobile de Patrice____\r\n4-Philippe à été en contact professionnel avec Collette____\r\n5-Colette à deux enfants____', 'Les gens - Choisissez Vrai ou Faux .', 'faux,vrai,vrai,faux,vrai,faux', NULL),
(17, 'Patrice,Patrice,Antoine', '', '1-Il n\'est pas chaleureux____\r\n2-Il n\'est pas franc____\r\n3-Il a le sens de l\'humour_____', 'Les gens -De qui parle-t-on ?', 'Jean-paul,Philippe,Patrice,Antoine', NULL),
(18, 'Non ce n\'est pas la peine', '', 'Tu veux que je l\'appelle?_____', 'Les gens - Choisissez une réponse possible .', 'Ca n\'a rien à voir,Ce n\'est pas gentil,Non ce n\'est pas la peine', NULL),
(21, 'Je vous présente,comment vous appelez-vous,Tiens c\'est bizarre,J\'ai bien reçu le document', '', '1_Vous présentez un collègue_______\r\n\r\n2-Vous demandez le nom de quelqu\'un_______\r\n\r\n3-Vous exprimez la surprse_______\r\n\r\n4-Vous confirmez que vous avez reçu un document_______', 'Au Bureau - Que dites vous dans chacune des situations suivantes ?', 'Tiens c\'est bizarre,Je vous présente,comment vous appelez-vous,J\'ai bien reçu le document', NULL),
(22, 'vraiment,horreur,sports,comme,pour', NULL, '1-Tu aimes faire du sport ? -Non pas_____!\r\n2-Il aime le foot ? -Ah non il a____ de ça !\r\n3-Vous partez aux____ d\'hiver ?\r\n4-_____ il n\'aime pas le vélo ,il ne viendra pas avec nous .\r\n5-J\'aime beacoup la nature , c\'est_____ ça que je fais de la randonnée .\r\n', 'Le sport - remplacez les termes suivants dans les phrases .', 'comme,pour,vraiment,sports,horreur', NULL),
(23, 'd\'hiver,préfère,vraiment,pour', NULL, '1-Elle ira aux sports_____.\r\n2-Il____ cent fois le tennis .\r\n3-Il aime le sport ? Non pas_____\r\n4-C\'est____ ça qu\'ils vont aux sports d\'hiver .', 'Le sport - Choisissez la bonne réponse ', ' d\'hiver,bien,pour,adore,préfère,passera,vraiment', NULL),
(24, 'égoïste,hypocrite,audacieuse,chaleureux,ignorant', '', '1.Est-ce qu\'elle est généreuse ? - Non, elle est_____\r\n2.Il est franc ? -Non, il est_____\r\n3.Elle est plutôt timide ? -Non , elle est_____\r\n4.Il est assez froid ? -Non, Il est_____\r\n5.C\'est quelqu\'un de cultivé ? -Non ,c\'est un____', 'Les gens - Répondez par le contraire .', 'chaleureux,hypocrite,audacieuse,ignorant,égoïste', NULL),
(25, 'Cyprien est invité à un dîner chez des amis,Il remarque Amélie,Il la trouve intéressante,Il commence à lui parler,Décidément  elle lui plaît', '', '_____                     ,____                    ,_____               ,_____               ,_____           \r\n        ', 'Les gens - Remettez l\'histoire dans un ordre logique .', 'Il remarque Amélie,Il la trouve intéressante,Cyprien est invité à un dîner chez des amis,Décidément  elle lui plaît,Il commence à lui parler', NULL),
(26, 'Elle est bizarre cette fille,C\'est quelqu\'un de complètement stupide,Qu\'elle est arrogante,C\'est quelqu\'un d\'hpocrite c\'est certain', '', '____,____,____,____', 'Les gens - Vous parlez d\'une femme que vous détestez.Choisissez les phrases adaptées.', 'C\'est quelqu\'un de très sympa,Elle est bizarre cette fille,Je l\'aime bien,C\'est quelqu\'un de complètement stupide,Qu\'elle est arrogante,C\'est quelqu\'un d\'hpocrite c\'est certain', NULL),
(27, 'aime,aime,aime,déteste,aime pas', '', '1-Michel est mon grand amour, je l\'____,\r\n   2- Ma voisine est sympathique, je l\'____,\r\n   3- Anne est une grande amie, je l\'____,\r\n   4- Raymond est méchant, je le ____,\r\n    5-Franck est bizarre, je ne l\'____', 'Les gens - Complétez par aimer ou détester ', 'déteste,aime pas,aime,aime,aime', NULL),
(28, 'sur,sous,à,chez,avec,dans', '', '1.Le livre est_____ la table .\r\n2.Le chat est_____ la chaise .\r\n3.Je vais_____ l\'école .\r\n4.Marie habite_____ ses parents .\r\n5.Paul mange_____ son ami .\r\n6.Les clés sont_____ le sac .', 'préposition,conjonction de coordination - Grammaire', 'à,dans,sur,sous,avec,chez', NULL),
